class Solution:
    def primePalindrome(self, n: int) -> int:
        def isPal(x):
            s = str(x)
            return s == s[::-1]
        def isPrime(x):
            if x < 2:
                return False
            d = 2
            while d * d <= x:
                if x % d == 0:
                    return False
                d += 1
            return True
        x = n
        while True:
            if isPal(x) and isPrime(x):
                return x
            x += 1

