var primePalindrome = function(n) {
    if (n >= 8 && n <= 11) return 11;
    const isPrime = x => {
        if (x < 2) return false;
        for (let d = 2; d * d <= x; d++) if (x % d === 0) return false;
        return true;
    };
    for (let r = 1;; r++) {
        const s = String(r);
        const p = Number(s + [...s.slice(0, -1)].reverse().join(''));
        if (p >= n && isPrime(p)) return p;
    }
};
